class Bag:
    def __init__(self, items):
        self.items = items

    def __iter__(self):
        return iter(self.items)

for item in Bag([1, 2]):
    print(item)

class Countdown:
    def __init__(self, n):
        self.n = n

    def __iter__(self):
        return self

    def __next__(self):
        if self.n <= 0:
            raise StopIteration
        value = self.n
        self.n -= 1
        return value

for x in Countdown(3):
    print(x)

def squares(n):
    for i in range(1, n + 1):
        yield i * i

for value in squares(3):
    print(value)

def acc():
    total = 0
    while True:
        x = yield total
        if x is None:
            return
        total += x

g = acc()
print(next(g))
print(g.send(5))
print(g.send(7))
try:
    g.send(None)
except StopIteration:
    print("done")

def worker():
    try:
        while True:
            yield "tick"
    except ValueError as err:
        print("caught", err)
        yield "recovered"

g = worker()
print(next(g))
print(g.throw(ValueError("boom")))

class Matrix:
    def __init__(self, rows):
        self.rows = rows

    def __iter__(self):
        for row in self.rows:
            for value in row:
                yield value

    def __reversed__(self):
        for row in reversed(self.rows):
            for value in reversed(row):
                yield value

m = Matrix([[1, 2], [3, 4]])
print(list(m))
print(list(reversed(m)))
